import{_ as a,o as t,c as r,a2 as o}from"./chunks/framework.BXA5Pi9t.js";const g=JSON.parse('{"title":"Ceph Developer Summit   Dashboard","description":"","frontmatter":{"title":"Ceph Developer Summit   Dashboard","date":"2025-09-11T00:00:00.000Z","updated":"2025-09-12T00:00:00.000Z","tags":["Ceph","Dashboard","NVMe-oF","Multi-Cluster","RGW"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2025/Ceph_Developer_Summit_Dashboard.md","filePath":"posts/2025/Ceph_Developer_Summit_Dashboard.md","lastUpdated":1780459816000}'),l={name:"posts/2025/Ceph_Developer_Summit_Dashboard.md"};function s(i,e,n,p,h,u){return t(),r("div",null,[...e[0]||(e[0]=[o('<p>本次Ceph开发者峰会Dashboard会议主要讨论了Ceph Dashboard在Tentacle版本中的关键改进以及Umbrella版本的未来规划。以下是会议的主要内容和决定事项：</p><h3 id="tentacle-release-主要亮点" tabindex="-1">Tentacle Release 主要亮点 <a class="header-anchor" href="#tentacle-release-主要亮点" aria-label="Permalink to &quot;Tentacle Release 主要亮点&quot;">​</a></h3><ol><li><strong>NVMe over TCP (NVMe-oF) 支持</strong>：升级支持最新规范的NVMe-oF Gateway Groups，并允许用户一次性创建多个Namespace。</li><li><strong>多集群支持（Multi-Cluster Support）</strong>：新增Multi-Cluster标签页，支持连接Hub Cluster并查看跨集群的Metrics。</li><li><strong>RGW (RADOS Gateway) 功能增强</strong>：包括Multi-Site自动化、Tiering Storage Classes支持、RGW Topics和S3 Bucket通知管理，以及Granular Bucket Replication改进。</li><li><strong>SMB 协议支持</strong>：新增SMB协议的完整管理及监控功能。</li><li><strong>监控与 Grafana 集成</strong>：新增NVMe、SFS、SMB协议的监控面板，支持按协议查看存储使用情况。</li><li><strong>Carbon 设计系统引入</strong>：采用Carbon Design System，对Dashboard UI进行全面现代化改造，提升用户体验。</li><li><strong>测试与基础设施改进</strong>：提升Testing Coverage和CI/CD流程，升级Grafana &amp; Angular版本。</li></ol><h3 id="umbrella-release-未来规划" tabindex="-1">Umbrella Release 未来规划 <a class="header-anchor" href="#umbrella-release-未来规划" aria-label="Permalink to &quot;Umbrella Release 未来规划&quot;">​</a></h3><ol><li><strong>文档优化</strong>：补齐Tentacle新增功能的文档，确保与代码同步。</li><li><strong>100% Carbon 化</strong>：继续推进NVMe-oF UI优化，改进Notification系统，优化大规模集群下的告警展示。</li><li><strong>弃用旧版 Dashboard</strong>：移除旧版Dashboard（v2），仅保留v3，不再支持回退。</li><li><strong>性能优化</strong>：提升Dashboard在大型集群（10,000+ OSDs）下的性能，降低CPU/Memory开销。</li><li><strong>新功能探索</strong>：计划实现Multi-Tenancy &amp; S3 Browser，优化REST API设计，引入AI辅助Troubleshooting功能。</li><li><strong>其他改进</strong>：更新Tools &amp; Packages，优化Troubleshooting，提升Dashboard在异常场景下的可用性。</li></ol><p>会议还展示了Tentacle版本中Dashboard UI的改进，包括Multi-Cluster管理界面、NVMe-oF Gateway配置、RGW Multi-Site Wizard、SMB管理界面、Grafana监控面板等。</p><p>后续行动计划包括继续推进Umbrella Release功能开发、完善文档、实验性开发AI辅助Troubleshooting功能，以及移除旧版Dashboard。</p><p>以上是对Ceph Developer Summit Dashboard会议的改进总结，涵盖了会议的关键细节、主要议题、决定事项以及后续行动计划，并保留了相关领域的英文原文关键词。</p>',8)])])}const m=a(l,[["render",s]]);export{g as __pageData,m as default};
